  "skill": "deploy_service",
  "precondition": {
    "op": "and",
    "args": [
      {
        "op": "is_true",
        "arg": {
          "var": "authenticated",
          "when": "before"
        }
      },
      {
        "op": "not",
        "arg": {
          "op": "is_null",
          "arg": {
            "var": "target_region",
            "when": "before"
          }
        }
      },
      {
        "op": "in_set",
        "value": {
          "var": "target_region",
          "when": "before"
        },
        "set": "valid_regions"
      },
      {
        "op": "not",
        "arg": {
          "op": "in_set",
          "value": {
            "var": "target_region",
            "when": "before"
          },
          "set": "rejected_regions"
        }
      },
      {
        "op": "not",
        "arg": {
          "op": "is_null",
          "arg": {
            "var": "cluster_tier",
            "when": "before"
          }
        }
      },
      {
        "op": "in_set",
        "value": {
          "var": "cluster_tier",
          "when": "before"
        },
        "set": "valid_cluster_tiers"
      },
      {
        "op": "not",
        "arg": {
          "op": "in_set",
          "value": {
            "var": "cluster_tier",
            "when": "before"
          },
          "set": "rejected_cluster_tiers"
        }
      }
    ]
  },
  "postcondition": {
    "op": "and",
    "args": [
      {
        "op": "eq",
        "left": {
          "var": "deployment_status",
          "when": "after"
        },
        "right": {
          "const": "deployed"
        }
      },
      {
        "op": "eq",
        "left": {
          "var": "active_deployment",
          "when": "after"
        },
        "right": {
          "op": "union",
          "left": {
            "var": "active_deployment",
            "when": "before"
          },
          "right": {
            "var": "allocated_resources",
            "when": "after"
          }
        }
      },
      {
        "op": "eq",
        "left": {
          "var": "available_quota",
          "when": "after"
        },
        "right": {
          "op": "difference",
          "left": {
            "var": "available_quota",
            "when": "before"
          },
          "right": {
            "var": "allocated_resources",
            "when": "after"
          }
        }
      },
      {
        "op": "eq",
        "left": {
          "var": "active_size",
          "when": "after"
        },
        "right": {
          "op": "union",
          "left": {
            "var": "active_size",
            "when": "before"
          },
          "right": {
            "var": "allocation_size",
            "when": "after"
          }
        }
      },
      {
        "op": "unchanged",
        "vars": [
          "authenticated",
          "target_region",
          "cluster_tier",
          "quota_size"
        ]
      }
    ]
  }
}
```

